/**
 * Temporal anti-aliasing and upscaling on a planet — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of the passes and the
 * material plugin below, loaded only by dynamic `import()` from the planet
 * view, where the visitor's tier or choice smooths edges over frames.
 *
 * Two passes go first on the camera. The scene is drawn into the first's own
 * texture, a fraction of a pixel off each frame (the projection's jitter,
 * temporal.ts) and at the share of the screen asked. The first (the resolve)
 * blends that frame into the picture kept from the frames before, at the
 * screen's size, writing it into one of two textures that take turns as the
 * history; the second copies it on to the passes after (the eye, the bloom)
 * or the screen. Babylon's own TAA pipeline does not fit: it has no
 * upscaling, and it needs every material to draw its motion into extra
 * targets, which the planet's sky, clouds and water shaders do not.
 *
 * Where the history was is worked out from the depth the scene was drawn
 * with and the camera's motion (temporal.ts `reprojection`), the nearest
 * depth about the pixel taken so edges keep their own. What the camera's
 * motion does not explain is held back: the history is kept within the
 * colours about the pixel this frame, and a pixel marked as moving by itself
 * (alpha over 1) leans on its present. The water marks itself: its blend adds
 * its alpha to the bed's 1. The swaying leaves and plants are marked by the
 * plugin here, while they sway. The clouds drift far less than a pixel a
 * frame, and move with the sky as the camera turns, which the depth gives.
 *
 * The blend is done on colours compressed by their brightness, so one bright
 * pixel does not flicker through the history. As eyeChunk.ts does, each pass
 * is written in WGSL for WebGPU and GLSL for WebGL2, kept in step.
 */
import { PostProcess } from '@babylonjs/core/PostProcesses/postProcess';
import { MaterialPluginBase } from '@babylonjs/core/Materials/materialPluginBase';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { ShaderStore } from '@babylonjs/core/Engines/shaderStore';
import { Constants } from '@babylonjs/core/Engines/constants';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import { Matrix } from '@babylonjs/core/Maths/math.vector';
import type { Effect } from '@babylonjs/core/Materials/effect';
import type { Observer } from '@babylonjs/core/Misc/observable';
import type { RenderTargetWrapper } from '@babylonjs/core/Engines/renderTargetWrapper';
import type { Scene } from '@babylonjs/core/scene';
import type { TemporalHandle } from './planetView';
import { TEMPORAL, continuous, jitterAt, jitterNdc, jitterPhases, reprojection, type CameraPose } from './temporal';
import { materialArrivals } from './materialArrivals';

const f = (x: number) => (Number.isInteger(x) ? `${x}.0` : String(x));

/** The least share of the screen drawn: below it there is too little to rebuild from. */
const MIN_SHARE = 0.5;
/** Babylon's `Camera.PERSPECTIVE_CAMERA`, written out so the chunk takes the camera's type alone. */
const PERSPECTIVE = 0;

// ---- GLSL (WebGL) ----

const RESOLVE_GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
uniform sampler2D historySampler;
uniform highp sampler2D depthSampler;
uniform mat4 reprojection;
uniform vec2 jitter;
uniform vec2 inputSize;
uniform vec2 depthNdc;
uniform float share;
uniform float reset;
float luma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
// Compressed by its brightness, then as luma and two chroma, where the colours about a pixel make a tight box.
vec3 toBox(vec3 c) {
  c = max(c, vec3(0.0));
  c /= 1.0 + luma(c);
  return vec3(dot(c, vec3(0.25, 0.5, 0.25)), dot(c, vec3(0.5, 0.0, -0.5)), dot(c, vec3(-0.25, 0.5, -0.25)));
}
vec3 fromBox(vec3 b) {
  vec3 c = max(vec3(b.x + b.y - b.z, b.x + b.z, b.x - b.y - b.z), vec3(0.0));
  return c / max(1.0 - luma(c), 0.001);
}
// The history at uv, sharp: Catmull-Rom from five bilinear samples.
vec3 historyAt(vec2 uv) {
  vec2 size = vec2(textureSize(historySampler, 0));
  vec2 p = uv * size;
  vec2 c1 = floor(p - 0.5) + 0.5;
  vec2 t = p - c1;
  vec2 w0 = t * (-0.5 + t * (1.0 - 0.5 * t));
  vec2 w1 = 1.0 + t * t * (-2.5 + 1.5 * t);
  vec2 w2 = t * (0.5 + t * (2.0 - 1.5 * t));
  vec2 w3 = t * t * (-0.5 + 0.5 * t);
  vec2 w12 = w1 + w2;
  vec2 m = (c1 + w2 / w12) / size;
  vec2 a = (c1 - 1.0) / size;
  vec2 b = (c1 + 2.0) / size;
  vec3 s = texture2D(historySampler, vec2(m.x, a.y)).rgb * w12.x * w0.y
    + texture2D(historySampler, vec2(a.x, m.y)).rgb * w0.x * w12.y
    + texture2D(historySampler, m).rgb * w12.x * w12.y
    + texture2D(historySampler, vec2(b.x, m.y)).rgb * w3.x * w12.y
    + texture2D(historySampler, vec2(m.x, b.y)).rgb * w12.x * w3.y;
  float w = w12.x * w0.y + w0.x * w12.y + w12.x * w12.y + w3.x * w12.y + w12.x * w3.y;
  return max(s / w, vec3(0.0));
}
void main(void) {
  ivec2 last = ivec2(inputSize) - 1;
  vec2 p = vUV * inputSize + jitter;
  ivec2 t = clamp(ivec2(floor(p)), ivec2(0), last);
  vec2 d = p - (vec2(t) + 0.5);
  vec3 m1 = vec3(0.0);
  vec3 m2 = vec3(0.0);
  vec3 lo = vec3(1e9);
  vec3 hi = vec3(-1e9);
  vec3 centre = vec3(0.0);
  float mark = 0.0;
  float near = 2.0;
  ivec2 nearAt = t;
  for (int y = -1; y <= 1; y++) {
    for (int x = -1; x <= 1; x++) {
      ivec2 q = clamp(t + ivec2(x, y), ivec2(0), last);
      vec4 s = texelFetch(textureSampler, q, 0);
      vec3 c = toBox(s.rgb);
      if (x == 0 && y == 0) centre = c;
      m1 += c;
      m2 += c * c;
      lo = min(lo, c);
      hi = max(hi, c);
      mark = max(mark, s.a);
      float z = texelFetch(depthSampler, q, 0).r;
      if (z < near) { near = z; nearAt = q; }
    }
  }
  vec3 mean = m1 / 9.0;
  vec3 sigma = sqrt(max(m2 / 9.0 - mean * mean, vec3(0.0)));
  // Where the nearest surface about the pixel was drawn the frame before, and so how far the picture moved.
  vec2 at = (vec2(nearAt) + 0.5) / inputSize;
  vec4 before = reprojection * vec4(at * 2.0 - 1.0, near * depthNdc.x + depthNdc.y, 1.0);
  vec2 beforeUv = before.xy / before.w * 0.5 + 0.5;
  vec2 uv = vUV + beforeUv - (vec2(nearAt) + 0.5 - jitter) / inputSize;
  vec3 soft = toBox(texture2D(textureSampler, p / inputSize).rgb);
  bool marked = mark > ${f(TEMPORAL.markAbove)};
  bool valid = reset < 0.5 && before.w > 0.0 && uv.x >= 0.0 && uv.y >= 0.0 && uv.x <= 1.0 && uv.y <= 1.0;
  vec3 result = soft;
  if (valid) {
    float g = marked ? ${f(TEMPORAL.gammaAnimated)} : ${f(TEMPORAL.gamma)};
    vec3 h = clamp(toBox(historyAt(uv)), max(lo, mean - g * sigma), min(hi, mean + g * sigma));
    float w = exp(-0.5 * dot(d, d) / (share * share) / ${f(TEMPORAL.sigma * TEMPORAL.sigma)});
    float a = ${f(TEMPORAL.feedback)} * w;
    vec3 now = centre;
    if (marked) { a = max(a, ${f(TEMPORAL.animatedShare)}); now = soft; }
    result = mix(h, now, a);
  }
  gl_FragColor = vec4(fromBox(result), 1.0);
}`;

// The copy on to the passes after; where the scene was upscaled, sharpened as AMD's contrast-adaptive sharpening
// does: each pixel pushed from its four neighbours by as much as their spread leaves room for, on colours
// compressed by brightness. The history itself is never sharpened.
const COPY_GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
#ifdef SHARPEN
vec3 squash(vec3 c) { c = max(c, vec3(0.0)); return c / (1.0 + c); }
#endif
void main(void) {
  vec4 c = texture2D(textureSampler, vUV);
#ifdef SHARPEN
  ivec2 at = ivec2(vUV * vec2(textureSize(textureSampler, 0)));
  vec3 m = squash(c.rgb);
  vec3 n = squash(texelFetch(textureSampler, clamp(at + ivec2(0, 1), ivec2(0), textureSize(textureSampler, 0) - 1), 0).rgb);
  vec3 s = squash(texelFetch(textureSampler, clamp(at - ivec2(0, 1), ivec2(0), textureSize(textureSampler, 0) - 1), 0).rgb);
  vec3 e = squash(texelFetch(textureSampler, clamp(at + ivec2(1, 0), ivec2(0), textureSize(textureSampler, 0) - 1), 0).rgb);
  vec3 w = squash(texelFetch(textureSampler, clamp(at - ivec2(1, 0), ivec2(0), textureSize(textureSampler, 0) - 1), 0).rgb);
  vec3 lo = min(m, min(min(n, s), min(e, w)));
  vec3 hi = max(m, max(max(n, s), max(e, w)));
  vec3 amp = sqrt(clamp(min(lo, 1.0 - hi) / max(hi, vec3(0.0001)), 0.0, 1.0));
  vec3 k = -amp / ${f(8 - 3 * TEMPORAL.sharpen)};
  vec3 r = clamp((m + k * (n + s + e + w)) / (1.0 + 4.0 * k), 0.0, 0.999);
  c.rgb = r / (1.0 - r);
#endif
  gl_FragColor = c;
}`;

// ---- WGSL (WebGPU): the same passes, in Babylon's WGSL post-process dialect. ----

const RESOLVE_WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
var historySamplerSampler: sampler;
var historySampler: texture_2d<f32>;
var depthSampler: texture_depth_2d;
uniform reprojection: mat4x4f;
uniform jitter: vec2f;
uniform inputSize: vec2f;
uniform depthNdc: vec2f;
uniform share: f32;
uniform reset: f32;
fn luma(c: vec3f) -> f32 { return dot(c, vec3f(0.2126, 0.7152, 0.0722)); }
fn toBox(c0: vec3f) -> vec3f {
  var c = max(c0, vec3f(0.0));
  c = c / (1.0 + luma(c));
  return vec3f(dot(c, vec3f(0.25, 0.5, 0.25)), dot(c, vec3f(0.5, 0.0, -0.5)), dot(c, vec3f(-0.25, 0.5, -0.25)));
}
fn fromBox(b: vec3f) -> vec3f {
  let c = max(vec3f(b.x + b.y - b.z, b.x + b.z, b.x - b.y - b.z), vec3f(0.0));
  return c / max(1.0 - luma(c), 0.001);
}
fn hist(uv: vec2f) -> vec3f {
  return textureSampleLevel(historySampler, historySamplerSampler, uv, 0.0).rgb;
}
fn historyAt(uv: vec2f) -> vec3f {
  let size = vec2f(textureDimensions(historySampler, 0));
  let p = uv * size;
  let c1 = floor(p - 0.5) + 0.5;
  let t = p - c1;
  let w0 = t * (-0.5 + t * (1.0 - 0.5 * t));
  let w1 = 1.0 + t * t * (-2.5 + 1.5 * t);
  let w2 = t * (0.5 + t * (2.0 - 1.5 * t));
  let w3 = t * t * (-0.5 + 0.5 * t);
  let w12 = w1 + w2;
  let m = (c1 + w2 / w12) / size;
  let a = (c1 - 1.0) / size;
  let b = (c1 + 2.0) / size;
  let s = hist(vec2f(m.x, a.y)) * w12.x * w0.y
    + hist(vec2f(a.x, m.y)) * w0.x * w12.y
    + hist(m) * w12.x * w12.y
    + hist(vec2f(b.x, m.y)) * w3.x * w12.y
    + hist(vec2f(m.x, b.y)) * w12.x * w3.y;
  let w = w12.x * w0.y + w0.x * w12.y + w12.x * w12.y + w3.x * w12.y + w12.x * w3.y;
  return max(s / w, vec3f(0.0));
}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let last = vec2i(uniforms.inputSize) - 1;
  let p = input.vUV * uniforms.inputSize + uniforms.jitter;
  let t = clamp(vec2i(floor(p)), vec2i(0), last);
  let d = p - (vec2f(t) + 0.5);
  var m1 = vec3f(0.0);
  var m2 = vec3f(0.0);
  var lo = vec3f(1e9);
  var hi = vec3f(-1e9);
  var centre = vec3f(0.0);
  var mark = 0.0;
  var near = 2.0;
  var nearAt = t;
  for (var y = -1; y <= 1; y++) {
    for (var x = -1; x <= 1; x++) {
      let q = clamp(t + vec2i(x, y), vec2i(0), last);
      let s = textureLoad(textureSampler, q, 0);
      let c = toBox(s.rgb);
      if (x == 0 && y == 0) { centre = c; }
      m1 += c;
      m2 += c * c;
      lo = min(lo, c);
      hi = max(hi, c);
      mark = max(mark, s.a);
      let z = textureLoad(depthSampler, q, 0);
      if (z < near) { near = z; nearAt = q; }
    }
  }
  let mean = m1 / 9.0;
  let sigma = sqrt(max(m2 / 9.0 - mean * mean, vec3f(0.0)));
  let at = (vec2f(nearAt) + 0.5) / uniforms.inputSize;
  let before = uniforms.reprojection * vec4f(at * 2.0 - 1.0, near * uniforms.depthNdc.x + uniforms.depthNdc.y, 1.0);
  let beforeUv = before.xy / before.w * 0.5 + 0.5;
  let uv = input.vUV + beforeUv - (vec2f(nearAt) + 0.5 - uniforms.jitter) / uniforms.inputSize;
  let smoothed = toBox(textureSampleLevel(textureSampler, textureSamplerSampler, p / uniforms.inputSize, 0.0).rgb);
  let marked = mark > ${f(TEMPORAL.markAbove)};
  let valid = uniforms.reset < 0.5 && before.w > 0.0 && all(uv >= vec2f(0.0)) && all(uv <= vec2f(1.0));
  var result = smoothed;
  if (valid) {
    var g = ${f(TEMPORAL.gamma)};
    if (marked) { g = ${f(TEMPORAL.gammaAnimated)}; }
    let h = clamp(toBox(historyAt(uv)), max(lo, mean - g * sigma), min(hi, mean + g * sigma));
    let w = exp(-0.5 * dot(d, d) / (uniforms.share * uniforms.share) / ${f(TEMPORAL.sigma * TEMPORAL.sigma)});
    var a = ${f(TEMPORAL.feedback)} * w;
    var now = centre;
    if (marked) { a = max(a, ${f(TEMPORAL.animatedShare)}); now = smoothed; }
    result = mix(h, now, a);
  }
  fragmentOutputs.color = vec4f(fromBox(result), 1.0);
}`;

const COPY_WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
#ifdef SHARPEN
fn squash(c: vec3f) -> vec3f { let d = max(c, vec3f(0.0)); return d / (1.0 + d); }
fn at(p: vec2i) -> vec3f { return squash(textureLoad(textureSampler, clamp(p, vec2i(0), vec2i(textureDimensions(textureSampler, 0)) - 1), 0).rgb); }
#endif
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  var c = textureSampleLevel(textureSampler, textureSamplerSampler, input.vUV, 0.0);
#ifdef SHARPEN
  let p = vec2i(input.vUV * vec2f(textureDimensions(textureSampler, 0)));
  let m = squash(c.rgb);
  let n = at(p + vec2i(0, 1));
  let s = at(p - vec2i(0, 1));
  let e = at(p + vec2i(1, 0));
  let w = at(p - vec2i(1, 0));
  let lo = min(m, min(min(n, s), min(e, w)));
  let hi = max(m, max(max(n, s), max(e, w)));
  let amp = sqrt(clamp(min(lo, 1.0 - hi) / max(hi, vec3f(0.0001)), vec3f(0.0), vec3f(1.0)));
  let k = -amp / ${f(8 - 3 * TEMPORAL.sharpen)};
  let r = clamp((m + k * (n + s + e + w)) / (1.0 + 4.0 * k), vec3f(0.0), vec3f(0.999));
  c = vec4f(r / (1.0 - r), c.a);
#endif
  fragmentOutputs.color = c;
}`;

const SOURCES = {
  planetTemporal: [RESOLVE_GLSL, RESOLVE_WGSL],
  planetTemporalCopy: [COPY_GLSL, COPY_WGSL],
} as const;

// ---- the marks on what sways ----

const MARK_NAME = 'TemporalMark';

/** Whether a material sways now: its sway plugin (swayChunk.ts) is on it and enabled. */
const swaying = (m: Scene['materials'][number]): boolean => (m.pluginManager?.getPlugin('Sway') as { isEnabled?: boolean } | null | undefined)?.isEnabled === true;

/** Leaves and plants, which the sway moves: lit materials of those names. */
const mayMark = (m: Scene['materials'][number]): boolean => (m.name === 'leaves' || m.name === 'plants') && (m.getClassName() === 'PBRMaterial' || m.getClassName() === 'StandardMaterial');

/** Writes the mark into a swaying material's alpha, last; never where the material is blended, whose alpha is its blend. */
class TemporalMarkPlugin extends MaterialPluginBase {
  private _isEnabled = true;

  constructor(material: ConstructorParameters<typeof MaterialPluginBase>[0]) {
    super(material, MARK_NAME, 330, { TEMPORALMARK: false }, true, true);
  }

  get isEnabled(): boolean {
    return this._isEnabled;
  }

  set isEnabled(value: boolean) {
    if (this._isEnabled === value) return;
    this._isEnabled = value;
    this.markAllDefinesAsDirty();
    this._enable(value);
  }

  override getClassName(): string {
    return 'TemporalMarkPlugin';
  }

  override isCompatible(shaderLanguage: ShaderLanguage): boolean {
    return shaderLanguage === ShaderLanguage.GLSL || shaderLanguage === ShaderLanguage.WGSL;
  }

  override prepareDefines(defines: Parameters<MaterialPluginBase['prepareDefines']>[0]): void {
    (defines as unknown as Record<string, boolean>)['TEMPORALMARK'] = this._isEnabled && swaying(this._material);
  }

  override getCustomCode(shaderType: string): { [pointName: string]: string } | null {
    if (shaderType !== 'fragment') return null;
    const colour = this._material.getClassName() === 'PBRMaterial' ? 'finalColor' : 'color';
    return { CUSTOM_FRAGMENT_BEFORE_FRAGCOLOR: `#if defined(TEMPORALMARK) && !defined(ALPHABLEND)\n${colour}.a = ${f(TEMPORAL.mark)};\n#endif\n` };
  }
}

/** The passes' sources for the engine: WGSL on WebGPU, GLSL otherwise. */
export function temporalShaderLanguage(engineKind?: string): ShaderLanguage {
  return engineKind === 'webgpu' ? ShaderLanguage.WGSL : ShaderLanguage.GLSL;
}

export function createTemporal(scene: Scene, camera: Camera, opts: { engineKind?: string; upscale: number }): TemporalHandle {
  const engine = scene.getEngine();
  const language = temporalShaderLanguage(opts.engineKind);
  const wgsl = language === ShaderLanguage.WGSL;
  for (const [name, [glsl, wgslSource]] of Object.entries(SOURCES)) {
    const store = wgsl ? ShaderStore.ShadersStoreWGSL : ShaderStore.ShadersStore;
    store[`${name}PixelShader`] ??= wgsl ? wgslSource : glsl;
  }
  const share = Math.min(1, Math.max(MIN_SHARE, Number.isFinite(opts.upscale) ? opts.upscale : 1));
  const phases = jitterPhases(share);

  // The scene is drawn into the resolve's own texture, so it is HDR and keeps its depth; filtered, for the smooth read.
  const resolve = new PostProcess('planetTemporal', 'planetTemporal', {
    engine,
    size: share,
    uniforms: ['reprojection', 'jitter', 'inputSize', 'depthNdc', 'share', 'reset'],
    samplers: ['historySampler', 'depthSampler'],
    samplingMode: Constants.TEXTURE_BILINEAR_SAMPLINGMODE,
    textureType: Constants.TEXTURETYPE_HALF_FLOAT,
    shaderLanguage: language,
  });
  const copy = new PostProcess('planetTemporalCopy', 'planetTemporalCopy', { engine, size: 1, samplingMode: Constants.TEXTURE_BILINEAR_SAMPLINGMODE, shaderLanguage: language, ...(share < 1 ? { defines: '#define SHARPEN' } : {}) });
  // The resolve writes every pixel of it: nothing to clear.
  copy.autoClear = false;
  // First on the camera, before every pass there is and any made later.
  const placeFirst = () => {
    const active = camera._postProcesses.filter((p) => p !== null);
    if (active[0] === resolve && active[1] === copy) return;
    for (const p of [resolve, copy]) {
      const i = camera._postProcesses.indexOf(p);
      if (i >= 0) camera._postProcesses.splice(i, 1);
    }
    camera._postProcesses.unshift(resolve, copy);
  };
  camera.attachPostProcess(resolve, 0);
  camera.attachPostProcess(copy, 1);
  placeFirst();

  // The history: two screen-sized textures taking turns, one written while the other is read.
  let history: [RenderTargetWrapper, RenderTargetWrapper] | null = null;
  let write = 0;
  const makeHistory = (width: number, height: number) => {
    history?.forEach((h) => h.dispose());
    const make = () =>
      engine.createRenderTargetTexture({ width, height }, { generateMipMaps: false, generateDepthBuffer: false, type: Constants.TEXTURETYPE_HALF_FLOAT, samplingMode: Constants.TEXTURE_BILINEAR_SAMPLINGMODE, label: 'planetTemporalHistory' });
    history = [make(), make()];
  };

  let frame = 0;
  let jitterPx: [number, number] = [0, 0];
  let jitter: [number, number] = [0, 0];
  let drawn = { width: 1, height: 1 };
  let unjittered: number[] | null = null;
  let before: CameraPose | null = null;
  let reset = true;
  // Whether a picture has been made into the history yet, for `latest`.
  let made = false;
  const reproject = new Matrix();

  // The marks, on every leaves and plants material as it arrives.
  const marks: TemporalMarkPlugin[] = [];
  const arrivals = materialArrivals(scene);
  const markAll = () =>
    arrivals.take((m) => {
      if (!mayMark(m)) return;
      const had = m.pluginManager?.getPlugin(MARK_NAME) as TemporalMarkPlugin | null | undefined;
      if (had) {
        if (!marks.includes(had)) marks.push(had);
        had.isEnabled = true;
      } else marks.push(new TemporalMarkPlugin(m));
    });
  markAll();

  // Before the camera's frame is drawn, and before any target drawn for it: the frame's jitter on its projection.
  const jittering: Observer<Camera> = scene.onBeforeCameraRenderObservable.add((cam) => {
    if (cam !== camera) return;
    placeFirst();
    markAll();
    drawn = { width: Math.max(1, (engine.getRenderWidth(true) * share) | 0), height: Math.max(1, (engine.getRenderHeight(true) * share) | 0) };
    frame++;
    jitterPx = jitterAt(frame, phases);
    jitter = jitterNdc(jitterPx, drawn.width, drawn.height);
    const projection = camera.getProjectionMatrix();
    unjittered = [...projection.m];
    unjittered[8] = 0;
    unjittered[9] = 0;
    if (camera.mode !== PERSPECTIVE) {
      jitterPx = [0, 0];
      jitter = [0, 0];
      return;
    }
    projection.setRowFromFloats(2, jitter[0], jitter[1], projection.m[10]!, projection.m[11]!);
    scene.updateTransformMatrix();
  });

  resolve.onActivateObservable.add(() => {
    const width = engine.getRenderWidth(true);
    const height = engine.getRenderHeight(true);
    if (!history || history[0].width !== width || history[0].height !== height) {
      makeHistory(width, height);
      reset = true;
      made = false;
    }
    copy.inputTexture = history![write]!;
    // WebGL draws the scene's depth into a buffer it cannot read; give the target a depth texture instead.
    const target = resolve.inputTexture;
    if (!target.depthStencilTexture && target.width > 0) {
      try {
        const stencil = engine.isStencilEnable;
        target.createDepthStencilTexture(0, false, stencil, 1, stencil ? Constants.TEXTUREFORMAT_DEPTH24_STENCIL8 : Constants.TEXTUREFORMAT_DEPTH32_FLOAT);
      } catch {
        /* an engine without depth textures: the frames are blended without the history's motion */
      }
    }
  });

  resolve.onApplyObservable.add((effect: Effect) => {
    const depth = resolve.inputTexture.depthStencilTexture;
    const view = camera.getViewMatrix().m;
    const p = camera.globalPosition;
    const now: CameraPose = {
      position: [p.x, p.y, p.z],
      rotation: [view[0]!, view[1]!, view[2]!, view[4]!, view[5]!, view[6]!, view[8]!, view[9]!, view[10]!],
      projection: unjittered ?? [...camera.getProjectionMatrix().m],
    };
    const valid = !reset && depth !== null && before !== null && continuous(before.position, now.position);
    Matrix.FromArrayToRef(reprojection(now, jitter, before ?? now), 0, reproject);
    if (history) effect._bindTexture('historySampler', history[1 - write]!.texture);
    if (depth) effect._bindTexture('depthSampler', depth);
    effect.setMatrix('reprojection', reproject);
    effect.setFloat2('jitter', jitterPx[0], jitterPx[1]);
    effect.setFloat2('inputSize', resolve.width, resolve.height);
    // The depth as the projection gives it, 0 to 1 on WebGPU, -1 to 1 on WebGL.
    if (engine.isNDCHalfZRange) effect.setFloat2('depthNdc', 1, 0);
    else effect.setFloat2('depthNdc', 2, -1);
    effect.setFloat('share', share);
    effect.setFloat('reset', valid ? 0 : 1);
    before = now;
    reset = false;
    write = 1 - write;
    made = true;
  });

  return {
    // The history written last: after the flip above, the one not to be written next.
    latest: () => (made && history ? history[1 - write]!.texture : null),
    dispose() {
      scene.onBeforeCameraRenderObservable.remove(jittering);
      resolve.dispose(camera);
      copy.dispose(camera);
      history?.forEach((h) => h.dispose());
      history = null;
      arrivals.dispose();
      for (const m of marks) m.isEnabled = false;
      marks.length = 0;
      // The projection as the camera makes it, without the last frame's jitter.
      camera.getProjectionMatrix(true);
      scene.updateTransformMatrix();
    },
  };
}
